274:   function loadState() {
275:     try {
276:       const raw = localStorage.getItem(SAVE_KEY);
277:       if (!raw) return freshState();
278:       const saved = JSON.parse(raw);
279:       if (!saved || typeof saved !== "object") return freshState();
280:       const next = freshState();
281:       const numeric = [
282:         "cash", "totalEarned", "runEarned", "patties", "totalPatties", "clicks",
283:         "served", "runServed", "heat", "bestHeat", "franchises", "zoomiesUntil", "zoomiesReadyAt",
284:         "zoomiesUsed", "nextOrderId", "nextOrderAt", "lastSeen"
285:       ];
286:       numeric.forEach((key) => {
287:         if (Number.isFinite(Number(saved[key]))) next[key] = Number(saved[key]);
288:       });
289:       if (saved.upgrades && typeof saved.upgrades === "object") {
290:         UPGRADES.forEach((upgrade) => {
291:           const value = Number(saved.upgrades[upgrade.id]);
292:           if (Number.isFinite(value) && value >= 0) next.upgrades[upgrade.id] = Math.floor(value);
293:         });
