298:             next.achievements[achievement.id] = Number(saved.achievements[achievement.id]) || Date.now();
299:           }
300:         });
301:       }
302:       if (typeof saved.sound === "boolean") next.sound = saved.sound;
303:       if (Array.isArray(saved.orders)) {
304:         next.orders = saved.orders
305:           .filter((order) => order && Number.isFinite(Number(order.need)) && Number(order.need) > 0)
