310:             progress: Math.max(0, Math.min(Number(order.progress) || 0, Number(order.need))),
311:             reward: Math.max(1, Math.round(Number(order.reward) || 1)),
312:             customer: String(order.customer || "Regular"),
313:             emoji: String(order.emoji || "🍔"),
314:             dish: String(order.dish || "The Classic"),
315:             note: String(order.note || "extra napkins")
316:           }));
317:       }
318:       return next;
319:     } catch (error) {
320:       console.warn("FRYDAY save could not be loaded.", error);
321:       return freshState();
322:     }
