456:     state.orders.splice(index, 1);
457:     const multiplier = sizzleMultiplier();
458:     const earned = Math.max(1, Math.round(order.reward * multiplier));
459:     const bonus = Math.max(0, earned - order.reward);
460:     state.cash += earned;
461:     state.totalEarned += earned;
462:     state.runEarned += earned;
463:     state.served += 1;
464:     state.runServed += 1;
465:     state.heat = Math.min(100, state.heat + 2.4);
466:     state.bestHeat = Math.max(state.bestHeat, state.heat);
467:     if (state.served === 1) {
468:       window.clearTimeout(hintTimer);
469:       el.firstHint.classList.add("is-hidden");
470:     }
471:     events.push({ order, earned, bonus, rect });
472:   }
