1015:   function applyOfflineProgress() {
1016:     const elapsed = Math.max(0, (Date.now() - (Number(state.lastSeen) || Date.now())) / 1000);
1017:     if (elapsed < 75) return;
1018:     const rate = state.upgrades.grill * 0.65 * franchiseMultiplier();
1019:     if (rate <= 0) return;
1020:     const seconds = Math.min(elapsed, 4 * 60 * 60);
