}
button, input { font: inherit; }
button { -webkit-tap-highlight-color: transparent; }
body.modal-open { overflow: hidden; }
button:focus-visible { outline: 2px solid var(--gold); outline-offset: 3px; }
[hidden] { display: none !important; }

.ambient {
  position: fixed;
  border-radius: 50%;
