import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync } from 'node:fs';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':0';
const browser = await chromium.launch({ ...config.browser.launchOptions, headless: false, timeout: 30000 });
const save = {
  version: 1, cash: 100, totalEarned: 100, runEarned: 50, patties: 0, totalPatties: 50,
  clicks: 10, served: 5, runServed: 5, fullMeals: 0, walkouts: 0, heat: 0, bestHeat: 0,
  upgrades: { spatula: 1, grill: 0, sauce: 0, drivethru: 0, treats: 0 }, franchises: 0,
  zoomiesUntil: 0, zoomiesReadyAt: 0, zoomiesUsed: 0, achievements: {}, sound: false,
  orders: [], nextOrderId: 1, nextOrderAt: Date.now() + 6000, lastSeen: Date.now()
};
const context = await browser.newContext({ viewport: { width: 1280, height: 800 } });
await context.addInitScript(([key, value]) => localStorage.setItem(key, value), ['fryday-midnight-shift-v1', JSON.stringify(save)]);
const page = await context.newPage();
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
await page.goto('http://localhost:3000', { waitUntil: 'load', timeout: 45000 });
await page.waitForTimeout(1000);
const width = () => page.evaluate(() => parseFloat(document.querySelector('.ticket-timer i')?.style.width || '0'));
const before = await width();
await page.locator('#helpBtn').click();
await page.waitForTimeout(3000);
const during = await width();
await page.locator('[data-close="helpModal"]').last().click();
await page.waitForTimeout(1200);
const after = await width();
const queue = await page.evaluate(() => document.querySelector('#queueCount')?.textContent);
console.log(JSON.stringify({ before, during, after, queue, errors }, null, 2));
await browser.close().catch(() => {});
process.exit(0);

